args.sparql:
SELECT DISTINCT ?director ?directorLabel ?child ?childLabel WHERE {
  dbr:An_Event dbo:director ?director .
  OPTIONAL { ?director dbo:child ?child. }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
  OPTIONAL { ?child rdfs:label ?childLabel FILTER(lang(?childLabel) = "en") }
}

